const {chromium}=require('playwright');const fs=require('fs'),path=require('path'),{spawn}=require('child_process');
(async()=>{const root=path.resolve(__dirname,'..'),mode=process.argv[2]||'stills';const browser=await chromium.launch({executablePath:process.env.CHROME||'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-dev-shm-usage','--allow-file-access-from-files']});const page=await browser.newPage({viewport:{width:1920,height:1080},deviceScaleFactor:1});page.on('pageerror',e=>{throw e});await page.goto('file://'+root+'/index.html');await page.waitForFunction('window.READY === true');
if(mode==='stills'){for(const t of [0,3,6,10,13,15.4,16.2,17,17.8,18.6,20,23.5,27,31,35.5]){await page.evaluate(t=>render(t),t);await page.screenshot({path:root+'/qa/frame-'+t.toFixed(2)+'.png'});}console.log('stills complete');}
if(mode==='video'){const f=spawn('ffmpeg',['-y','-v','warning','-f','image2pipe','-vcodec','mjpeg','-r','24','-i','pipe:0','-an','-c:v','libx264','-preset','medium','-crf','17','-pix_fmt','yuv420p','-movflags','+faststart',root+'/picture.mp4'],{stdio:['pipe','inherit','inherit']});let closed=new Promise((res,rej)=>f.on('close',c=>c===0?res():rej(new Error('ffmpeg '+c))));for(let i=0;i<864;i++){await page.evaluate(t=>render(t),i/24);let b=await page.screenshot({type:'jpeg',quality:95});if(!f.stdin.write(b))await new Promise(r=>f.stdin.once('drain',r));if(i%120===0)console.log(i+'/864');}f.stdin.end();await closed;}
if(mode==='strip'){for(let i=0;i<=23;i++){let t=14.6+i*.2;await page.evaluate(t=>render(t),t);await page.screenshot({path:root+'/qa/action-'+t.toFixed(2)+'.jpg',type:'jpeg',quality:90});}}
if(mode==='determinism'){await page.evaluate(()=>render(20));let a=await page.screenshot();await page.evaluate(()=>render(2));await page.evaluate(()=>render(20));let b=await page.screenshot();fs.writeFileSync(root+'/qa/determinism.json',JSON.stringify({identical:a.equals(b),bytes:a.length}));}
fs.writeFileSync(root+'/events.json',JSON.stringify(await page.evaluate(()=>({duration:DUR,events:EV})),null,2));await browser.close()})().catch(e=>{console.error(e);process.exit(1)});
